#include "Rover.h"

// Where the X is, counting from the start.
const int GOAL_X = 8;  // cells right
const int GOAL_Y = 5;  // cells up

int x = 0;
int y = 0;
int dir = 0;  // 0 up, 1 right, 2 down, 3 left

void right() {
  turnRight();
  dir = (dir + 1) % 4;
}

void left() {
  turnLeft();
  dir = (dir + 3) % 4;
}

void face(int d) {
  if ((dir + 3) % 4 == d) {
    left();
  }
  while (dir != d) {
    right();
  }
}

void step() {
  forward(1);
  if (dir == 0) y++;
  if (dir == 1) x++;
  if (dir == 2) y--;
  if (dir == 3) x--;
}

int size(int n) {
  if (n < 0) {
    return -n;
  }
  return n;
}

int distance() {
  return size(GOAL_X - x) + size(GOAL_Y - y);
}

// Face a way that gets closer to the X and is open. false if there isn't one.
bool faceTowardGoal() {
  if (x < GOAL_X) {
    face(1);
    if (distanceAhead() > 0) return true;
  }
  if (x > GOAL_X) {
    face(3);
    if (distanceAhead() > 0) return true;
  }
  if (y < GOAL_Y) {
    face(0);
    if (distanceAhead() > 0) return true;
  }
  if (y > GOAL_Y) {
    face(2);
    if (distanceAhead() > 0) return true;
  }
  return false;
}

// Blocked: keep the wall on the right until we're closer than here
// and the way toward the X is open.
void followWall() {
  int stuck = distance();
  while (distanceAhead() == 0) {
    left();
  }
  step();
  bool following = true;
  while (following) {
    int heading = dir;
    if (distance() < stuck && faceTowardGoal()) {
      following = false;
    } else {
      face(heading);
      right();
      while (distanceAhead() == 0) {
        left();
      }
      step();
    }
  }
}

void setup() {
}

void loop() {
  if (faceTowardGoal()) {
    step();
  } else {
    followWall();
  }
}
